16	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
17	 */
18	export function createInvoice({ customerId, issueDate, lines }) {
19	  const customerResult = getCustomer(customerId);
20	  if (!customerResult.ok) return customerResult;
21	
22	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
23	
24	  if (!lines || lines.length === 0) return fail('NO_LINES');
25	
26	  const processedLines = [];
27	  for (const line of lines) {
28	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
29	
30	    const productResult = getProduct(line.sku);
31	    if (!productResult.ok) return productResult;
32	
33	    const product = productResult.value;
34	    processedLines.push({
35	      sku: line.sku,
36	      name: product.name,
37	      qty: line.qty,
38	      unitPrice: product.unitPrice,
39	      vatRate: product.vatRate,
40	    });
41	  }
42	
43	  return ok({
44	    customerId,
45	    issueDate,
46	    status: 'draft',
47	    lines: processedLines,
48	  });
49	}
