51	/**
52	 * Calculate the total amount for a single line item.
53	 * @param {{ qty: number, unitPrice: number }} line
54	 * @returns {number}
55	 */
56	export function lineTotal(line) {
57	  return line.qty * line.unitPrice;
58	}
