60	/**
61	 * Calculate subtotal and total for an invoice.
62	 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }} invoice
63	 * @returns {{ subtotal: number, total: number }}
64	 */
65	export function invoiceTotals(invoice) {
66	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
67	  return { subtotal, total: subtotal };
68	}
