70	/**
71	 * Add a line to an invoice or increase quantity if the SKU already exists.
72	 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
73	 * @param {{ sku: string, qty: number }} params
74	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
