import assert from 'node:assert';
import { describe, it } from 'node:test';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

describe('createInvoice', () => {
  it('creates a draft invoice with valid input', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(result.ok);
    assert.equal(result.value.customerId, 'C-001');
    assert.equal(result.value.issueDate, '2025-12-15');
    assert.equal(result.value.status, 'draft');
    assert.equal(result.value.lines.length, 2);
    assert.equal(result.value.lines[0].sku, 'DES-HOUR');
    assert.equal(result.value.lines[0].name, 'Design work (hour)');
    assert.equal(result.value.lines[0].qty, 5);
    assert.equal(result.value.lines[0].unitPrice, 8500);
    assert.equal(result.value.lines[0].vatRate, 21);
    assert.equal(result.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(result.value.lines[1].name, 'Development (hour)');
    assert.equal(result.value.lines[1].qty, 3);
  });

  it('returns CUSTOMER_NOT_FOUND for unknown customer', () => {
    const result = createInvoice({
      customerId: 'unknown-cust',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
  });

  it('returns DATE_INVALID for invalid date format', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '15-12-2025',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for non-existent date', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns DATE_INVALID for invalid format without dashes', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '20251215',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DATE_INVALID');
  });

  it('returns NO_LINES for empty lines array', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [],
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns NO_LINES for missing lines', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: undefined,
    });

    assert(!result.ok);
    assert.equal(result.error, 'NO_LINES');
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for fractional quantity', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 2.5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'INVALID', qty: 1 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'UNKNOWN_SKU');
  });

  it('does not mutate input lines', () => {
    const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
    const linesCopy = JSON.parse(JSON.stringify(inputLines));

    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: inputLines,
    });

    assert.deepEqual(inputLines, linesCopy);
  });

  it('accepts discount on a line', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 10);
  });

  it('accepts decimal discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 12.5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 12.5);
  });

  it('defaults discount to 0 when not provided', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(result.ok);
    assert.equal(result.value.lines[0].discountPercent, 0);
  });

  it('returns DISCOUNT_INVALID for negative discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: -5 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('returns DISCOUNT_INVALID for discount over 100', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 101 }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('returns DISCOUNT_INVALID for non-numeric discount', () => {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 'ten' }],
    });

    assert(!result.ok);
    assert.equal(result.error, 'DISCOUNT_INVALID');
  });

  it('accepts 0 and 100 as valid discount bounds', () => {
    const result1 = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 0 }],
    });

    assert(result1.ok);
    assert.equal(result1.value.lines[0].discountPercent, 0);

    const result2 = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DEV-HOUR', qty: 3, discountPercent: 100 }],
    });

    assert(result2.ok);
    assert.equal(result2.value.lines[0].discountPercent, 100);
  });
});

describe('lineTotal', () => {
  it('calculates qty times unitPrice', () => {
    const line = { qty: 5, unitPrice: 8500 };
    assert.equal(lineTotal(line), 42500);
  });

  it('handles single unit', () => {
    const line = { qty: 1, unitPrice: 1000 };
    assert.equal(lineTotal(line), 1000);
  });

  it('handles large quantities', () => {
    const line = { qty: 100, unitPrice: 5000 };
    assert.equal(lineTotal(line), 500000);
  });
});

describe('invoiceTotals', () => {
  it('calculates subtotal and total for a single line', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, 42500);
  });

  it('calculates subtotal and total for multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500 },
        { qty: 3, unitPrice: 9500 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500 + 28500);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, 42500 + 28500);
  });

  it('handles empty invoice', () => {
    const invoice = { lines: [] };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 0);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, 0);
  });

  it('works with invoice from createInvoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const expectedSubtotal = 5 * 8500 + 3 * 9500;
    assert.equal(totals.subtotal, expectedSubtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.total, expectedSubtotal);
  });

  it('calculates discount for a single line with 10% discount', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 10 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 4250);
    assert.equal(totals.total, 38250);
  });

  it('calculates discount with decimal percentage', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 12.5 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 5312.5);
    assert.equal(totals.total, 37187.5);
  });

  it('calculates total discount across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 5, unitPrice: 8500, discountPercent: 10 },
        { qty: 3, unitPrice: 9500, discountPercent: 20 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500 + 28500);
    assert.equal(totals.discount, 4250 + 5700);
    assert.equal(totals.total, 42500 + 28500 - 4250 - 5700);
  });

  it('clamps total at 0 when discount exceeds subtotal', () => {
    const invoice = {
      lines: [{ qty: 5, unitPrice: 8500, discountPercent: 100 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 42500);
    assert.equal(totals.discount, 42500);
    assert.equal(totals.total, 0);
  });

  it('handles mixed discounted and non-discounted lines', () => {
    const invoice = {
      lines: [
        { qty: 10, unitPrice: 1000, discountPercent: 0 },
        { qty: 5, unitPrice: 2000, discountPercent: 50 },
      ],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 10000 + 10000);
    assert.equal(totals.discount, 5000);
    assert.equal(totals.total, 15000);
  });

  it('works with invoice from createInvoice with discounts', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
        { sku: 'DEV-HOUR', qty: 3, discountPercent: 5 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 5 * 8500 + 3 * 9500;
    const discount = (5 * 8500) * 0.1 + (3 * 9500) * 0.05;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.total, subtotal - discount);
  });
});

describe('addLine', () => {
  it('adds a new line to an invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines.length, 2);
    assert.equal(addResult.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(addResult.value.lines[1].qty, 3);
    assert.equal(addResult.value.lines[1].name, 'Development (hour)');
  });

  it('increases qty if SKU already exists', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines.length, 1);
    assert.equal(addResult.value.lines[0].sku, 'DES-HOUR');
    assert.equal(addResult.value.lines[0].qty, 8);
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 0 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: -2 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for fractional quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 2.5 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'INVALID', qty: 1 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'UNKNOWN_SKU');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'sent',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'NOT_DRAFT');
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const originalLines = invoiceResult.value.lines.length;
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(invoiceResult.value.lines.length, originalLines);
  });
});

describe('removeLine', () => {
  it('removes a line from an invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(removeResult.ok);
    assert.equal(removeResult.value.lines.length, 1);
    assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  });

  it('returns LINE_NOT_FOUND for non-existent SKU', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'INVALID');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'LINE_NOT_FOUND');
  });

  it('returns NO_LINES if removing the last line', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'NO_LINES');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'sent',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const removeResult = removeLine(invoice, 'DES-HOUR');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'NOT_DRAFT');
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const originalLines = invoiceResult.value.lines.length;
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(removeResult.ok);
    assert.equal(invoiceResult.value.lines.length, originalLines);
  });
});

describe('issueInvoice', () => {
  it('issues a draft invoice with a number and status "issued"', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2025-0001');
    assert.equal(issueResult.value.status, 'issued');
    assert.equal(issueResult.value.customerId, 'C-001');
    assert.equal(issueResult.value.issueDate, '2025-12-15');
    assert.equal(issueResult.value.lines.length, 1);
  });

  it('assigns the next number when numbers already exist', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const issueResult = issueInvoice(invoiceResult.value, existingNumbers);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2025-0003');
  });

  it('assigns number from different year when issuing in new year', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-01-10',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const issueResult = issueInvoice(invoiceResult.value, existingNumbers);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2026-0001');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      number: 'INV-2025-0001',
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const issueResult = issueInvoice(invoice, []);

    assert(!issueResult.ok);
    assert.equal(issueResult.error, 'NOT_DRAFT');
  });

  it('preserves line items', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(issueResult.value.lines.length, 2);
    assert.equal(issueResult.value.lines[0].sku, 'DES-HOUR');
    assert.equal(issueResult.value.lines[0].qty, 5);
    assert.equal(issueResult.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(issueResult.value.lines[1].qty, 3);
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const originalStatus = invoiceResult.value.status;
    const originalLines = invoiceResult.value.lines.length;
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(invoiceResult.value.status, originalStatus);
    assert.equal(invoiceResult.value.lines.length, originalLines);
    assert(!invoiceResult.value.number);
  });
});

