1	import { getCustomer } from './customers.js';
2	import { getProduct } from './catalogue.js';
3	import { ok, fail } from './result.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	
6	function isValidDate(dateString) {
7	  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;
8	  const date = new Date(dateString + 'T00:00:00Z');
9	  if (isNaN(date.getTime())) return false;
10	  return date.toISOString().split('T')[0] === dateString;
11	}
12	
13	function isValidDiscount(discountPercent) {
14	  if (discountPercent === undefined || discountPercent === null) return true;
15	  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
16	}
17	
18	/**
19	 * Create a new draft invoice.
20	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
21	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
22	 */
23	export function createInvoice({ customerId, issueDate, lines }) {
24	  const customerResult = getCustomer(customerId);
25	  if (!customerResult.ok) return customerResult;
26	
27	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
28	
29	  if (!lines || lines.length === 0) return fail('NO_LINES');
30	
31	  const processedLines = [];
32	  for (const line of lines) {
33	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
34	
35	    if (!isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');
36	
37	    const productResult = getProduct(line.sku);
38	    if (!productResult.ok) return productResult;
39	
40	    const product = productResult.value;
41	    processedLines.push({
42	      sku: line.sku,
43	      name: product.name,
44	      qty: line.qty,
45	      unitPrice: product.unitPrice,
46	      vatRate: product.vatRate,
47	      discountPercent: line.discountPercent ?? 0,
48	    });
49	  }
50	
51	  return ok({
52	    customerId,
53	    issueDate,
54	    status: 'draft',
55	    lines: processedLines,
56	  });
57	}
58	
59	/**
60	 * Calculate the total amount for a single line item.
61	 * @param {{ qty: number, unitPrice: number }} line
62	 * @returns {number}
63	 */
64	export function lineTotal(line) {
65	  return line.qty * line.unitPrice;
66	}
67	
68	/**
69	 * Calculate subtotal and total for an invoice.
70	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
71	 * @returns {{ subtotal: number, discount: number, total: number }}
72	 */
73	export function invoiceTotals(invoice) {
74	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
75	  const discount = invoice.lines.reduce((sum, line) => {
76	    const lineDiscount = lineTotal(line) * (line.discountPercent ?? 0) / 100;
77	    return sum + Math.max(0, lineDiscount);
78	  }, 0);
79	  const total = Math.max(0, subtotal - discount);
80	  return { subtotal, discount, total };
81	}
82	
83	/**
84	 * Add a line to an invoice or increase quantity if the SKU already exists.
85	 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
86	 * @param {{ sku: string, qty: number, discountPercent?: number }} params
87	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
88	 */
89	export function addLine(invoice, { sku, qty, discountPercent }) {
90	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
91	
92	  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
93	
94	  if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');
95	
96	  const productResult = getProduct(sku);
97	  if (!productResult.ok) return productResult;
98	
99	  const product = productResult.value;
100	  const newLines = invoice.lines.map((line) => ({ ...line }));
101	  const existingIndex = newLines.findIndex((line) => line.sku === sku);
102	
103	  if (existingIndex >= 0) {
104	    newLines[existingIndex].qty += qty;
105	  } else {
106	    newLines.push({
107	      sku,
108	      name: product.name,
109	      qty,
110	      unitPrice: product.unitPrice,
111	      vatRate: product.vatRate,
112	      discountPercent: discountPercent ?? 0,
113	    });
114	  }
115	
116	  return ok({
117	    customerId: invoice.customerId,
118	    issueDate: invoice.issueDate,
119	    status: invoice.status,
120	    lines: newLines,
121	  });
122	}
123	
124	/**
125	 * Remove a line from an invoice by SKU.
126	 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
127	 * @param {string} sku
128	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
129	 */
130	export function removeLine(invoice, sku) {
131	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
132	
133	  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
134	  if (lineIndex < 0) return fail('LINE_NOT_FOUND');
135	
136	  if (invoice.lines.length === 1) return fail('NO_LINES');
137	
138	  const newLines = invoice.lines.filter((line) => line.sku !== sku);
139	
140	  return ok({
141	    customerId: invoice.customerId,
142	    issueDate: invoice.issueDate,
143	    status: invoice.status,
144	    lines: newLines,
145	  });
146	}
